package com.campus.placement;

import com.sun.net.httpserver.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.sql.*;import java.util.*;import java.util.concurrent.*;

public class Main {
 private static final Path STATIC=Path.of("src/main/resources/static").toAbsolutePath().normalize();
 private record User(long id,String name,String email,String role){}
 private static final Map<String,User> SESSIONS=new ConcurrentHashMap<>();
 private record Reset(String code,long expires){} private static final Map<String,Reset> RESETS=new ConcurrentHashMap<>();
 public static void main(String[] args)throws Exception{Database.initialize();HttpServer s=HttpServer.create(new InetSocketAddress("127.0.0.1",8080),0);s.createContext("/api/",Main::api);s.createContext("/",Main::staticFile);s.setExecutor(Executors.newFixedThreadPool(8));s.start();System.out.println("Placement portal: http://localhost:8080");}
 private static void api(HttpExchange x)throws IOException {try{String p=x.getRequestURI().getPath(),m=x.getRequestMethod();
  if(p.equals("/api/auth/register")&&m.equals("POST")){register(x);return;} if(p.equals("/api/auth/login")&&m.equals("POST")){login(x);return;}if(p.equals("/api/auth/logout")){SESSIONS.remove(token(x));json(x,200,Map.of("ok",true));return;}if(p.equals("/api/auth/me")){User u=user(x);json(x,200,u==null?Map.of("authenticated",false):row("authenticated",true,"id",u.id,"name",u.name,"email",u.email,"role",u.role));return;}
  if(p.equals("/api/auth/forgot")&&m.equals("POST")){String code=forgot(body(x));if(code==null)json(x,200,Map.of("ok",true,"message","No student account was found for that email."));else json(x,200,Map.of("ok",true,"code",code,"expiresInMinutes",10));return;}
  if(p.equals("/api/auth/reset")&&m.equals("POST")){reset(body(x));json(x,200,Map.of("ok",true));return;}  User u=user(x);
  if(p.equals("/api/drives")&&m.equals("GET")){json(x,200,drives());return;}
  if(p.equals("/api/companies")&&m.equals("GET")){json(x,200,companies());return;}
  if(p.equals("/api/admin/password")&&m.equals("PUT")){changeAdminPassword(u,body(x));json(x,200,Map.of("ok",true));return;}
  if(p.equals("/api/stats")&&m.equals("GET")){admin(u);json(x,200,stats());return;}
  if(p.equals("/api/profile")&&m.equals("GET")){student(u);json(x,200,profile(u.id));return;}
  if(p.equals("/api/profile")&&m.equals("PUT")){student(u);json(x,200,saveProfile(u.id,body(x)));return;}
  if(p.equals("/api/profile/roll-number")&&m.equals("PUT")){student(u);updateStudentCode(u.id,body(x));json(x,200,Map.of("ok",true));return;}
  if(p.equals("/api/applications")&&m.equals("GET")){if(u==null)throw new IllegalArgumentException("Please sign in.");json(x,200,applications(u));return;}
  if(p.matches("/api/applications/\\d+/history")&&m.equals("GET")){student(u);long aid=Long.parseLong(p.split("/")[3]);json(x,200,applicationHistory(aid,u.id));return;}
  if(p.matches("/api/drives/\\d+/apply")&&m.equals("POST")){student(u);long id=Long.parseLong(p.split("/")[3]);apply(u.id,id);json(x,201,Map.of("ok",true));return;}
  admin(u);  if(p.equals("/api/admin/companies")&&m.equals("POST")){json(x,201,saveCompany(body(x),0));return;}
  if(p.matches("/api/admin/companies/\\d+")&&m.equals("PUT")){json(x,200,saveCompany(body(x),Long.parseLong(p.substring(p.lastIndexOf('/')+1))));return;}
  if(p.matches("/api/admin/companies/\\d+")&&m.equals("DELETE")){deleteCompany(Long.parseLong(p.substring(p.lastIndexOf('/')+1)));json(x,200,Map.of("ok",true));return;}
  if(p.equals("/api/admin/drives")&&m.equals("POST")){json(x,201,saveDrive(body(x),0));return;}
  if(p.matches("/api/admin/drives/\\d+")&&m.equals("PUT")){json(x,200,saveDrive(body(x),Long.parseLong(p.substring(p.lastIndexOf('/')+1))));return;}
  if(p.matches("/api/admin/drives/\\d+")&&m.equals("DELETE")){deleteDrive(Long.parseLong(p.substring(p.lastIndexOf('/')+1)));json(x,200,Map.of("ok",true));return;}
  if(p.matches("/api/admin/drives/\\d+/applications")&&m.equals("GET")){json(x,200,driveApplicants(Long.parseLong(p.split("/")[4])));return;}
  if(p.matches("/api/admin/applications/\\d+")&&m.equals("PATCH")){updateApplication(Long.parseLong(p.substring(p.lastIndexOf('/')+1)),body(x),u.id);json(x,200,Map.of("ok",true));return;}
  json(x,404,Map.of("error","Route not found"));
 }catch(IllegalArgumentException e){json(x,400,Map.of("error",e.getMessage()));}catch(SecurityException e){json(x,401,Map.of("error",e.getMessage()));}catch(SQLException e){json(x,e.getSQLState()!=null&&e.getSQLState().startsWith("23")?409:500,Map.of("error",e.getSQLState()!=null&&e.getSQLState().startsWith("23")?"This record already exists or has applicants.":"Database request failed."));}catch(Exception e){e.printStackTrace();json(x,500,Map.of("error","Request failed."));}}
 private static void register(HttpExchange x)throws Exception{Map<String,Object>b=body(x);String name=req(b,"name",120),email=req(b,"email",180).toLowerCase(),studentCode=req(b,"studentCode",40),pw=req(b,"password",100);if(pw.length()<8)throw new IllegalArgumentException("Password must be at least 8 characters.");String branch=opt(b,"branch",100);int year=integer(b,"year",2020,2100);try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("INSERT INTO students(full_name,email,student_code,department,graduation_year,gpa,skills,resume_link,password_hash) VALUES(?,?,?,?,?,0,'','',?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,email);p.setString(3,studentCode);p.setString(4,branch.isBlank()?"Not set":branch);p.setInt(5,year);p.setString(6,Database.hash(pw));p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();session(x,new User(r.getLong(1),name,email,"STUDENT"));}}json(x,201,Map.of("ok",true));}
 private static void login(HttpExchange x)throws Exception{Map<String,Object>b=body(x);String email=req(b,"email",180).toLowerCase(),pw=req(b,"password",100);try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT id,full_name,email,department,password_hash FROM students WHERE email=?")){p.setString(1,email);try(ResultSet r=p.executeQuery()){if(!r.next()||!Database.verify(pw,r.getString("password_hash")))throw new SecurityException("Email or password is incorrect.");String role=r.getString("email").equals("admin@placement.local")?"ADMIN":"STUDENT";session(x,new User(r.getLong("id"),r.getString("full_name"),r.getString("email"),role));}}json(x,200,Map.of("ok",true));}
 private static String forgot(Map<String,Object>b)throws SQLException{String email=req(b,"email",180).toLowerCase();try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT id FROM students WHERE email=? AND email<>?")){p.setString(1,email);p.setString(2,"admin@placement.local");try(ResultSet r=p.executeQuery()){if(r.next()){String code=String.format("%06d",new java.security.SecureRandom().nextInt(1000000));RESETS.put(email,new Reset(code,System.currentTimeMillis()+600000));return code;}}}return null;}private static void reset(Map<String,Object>b)throws Exception{String email=req(b,"email",180).toLowerCase(),code=req(b,"code",6),pw=req(b,"password",100);if(pw.length()<8)throw new IllegalArgumentException("Password must be at least 8 characters.");Reset r=RESETS.get(email);if(r==null||r.expires<System.currentTimeMillis()||!java.security.MessageDigest.isEqual(r.code.getBytes(StandardCharsets.UTF_8),code.getBytes(StandardCharsets.UTF_8)))throw new IllegalArgumentException("Reset code is invalid or expired. Request a new code.");try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("UPDATE students SET password_hash=? WHERE email=? AND email<>?")){p.setString(1,Database.hash(pw));p.setString(2,email);p.setString(3,"admin@placement.local");if(p.executeUpdate()==0)throw new IllegalArgumentException("Account not found.");}RESETS.remove(email);}
 private static void changeAdminPassword(User u,Map<String,Object>b)throws Exception{admin(u);String old=req(b,"currentPassword",100),next=req(b,"newPassword",100);if(next.length()<8)throw new IllegalArgumentException("New password must be at least 8 characters.");try(Connection c=Database.connect();PreparedStatement q=c.prepareStatement("SELECT password_hash FROM students WHERE id=?")){q.setLong(1,u.id);try(ResultSet r=q.executeQuery()){if(!r.next()||!Database.verify(old,r.getString(1)))throw new SecurityException("Current password is incorrect.");}}try(Connection c=Database.connect();PreparedStatement q=c.prepareStatement("UPDATE students SET password_hash=? WHERE id=?")){q.setString(1,Database.hash(next));q.setLong(2,u.id);q.executeUpdate();}} private static void session(HttpExchange x,User u){String t=UUID.randomUUID().toString();SESSIONS.put(t,u);x.getResponseHeaders().add("Set-Cookie","PLACEMENT_SESSION="+t+"; Path=/; HttpOnly; SameSite=Lax");}
 private static String token(HttpExchange x){String h=x.getRequestHeaders().getFirst("Cookie");if(h!=null)for(String part:h.split(";")){String[] a=part.trim().split("=",2);if(a.length==2&&a[0].equals("PLACEMENT_SESSION"))return a[1];}return "";}
 private static User user(HttpExchange x){return SESSIONS.get(token(x));}private static void admin(User u){if(u==null||!u.role.equals("ADMIN"))throw new SecurityException("Admin sign-in required.");}private static void student(User u){if(u==null||!u.role.equals("STUDENT"))throw new SecurityException("Student sign-in required.");}
 private static List<Map<String,Object>> drives()throws SQLException{List<Map<String,Object>>o=new ArrayList<>();String q="SELECT d.id,d.company_id,d.title,d.location,d.package_lpa,d.eligibility_gpa,d.eligibility_branch,d.description,d.apply_by,d.status,c.name company,(SELECT COUNT(*) FROM applications a WHERE a.drive_id=d.id) applicants FROM drives d JOIN companies c ON c.id=d.company_id ORDER BY d.apply_by";try(Connection c=Database.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())o.add(row("id",r.getLong("id"),"companyId",r.getLong("company_id"),"company",r.getString("company"),"title",r.getString("title"),"location",r.getString("location"),"package",r.getBigDecimal("package_lpa"),"minGpa",r.getBigDecimal("eligibility_gpa"),"branches",r.getString("eligibility_branch"),"description",r.getString("description"),"applyBy",r.getDate("apply_by").toString(),"status",r.getString("status"),"applicants",r.getInt("applicants")));}return o;}
 private static List<Map<String,Object>> companies()throws SQLException{List<Map<String,Object>>o=new ArrayList<>();try(Connection c=Database.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,name,industry,location FROM companies ORDER BY name")){while(r.next())o.add(row("id",r.getLong(1),"name",r.getString(2),"industry",r.getString(3),"location",r.getString(4)));}return o;}
 private static Map<String,Object> profile(long id)throws SQLException{try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT id,full_name,email,student_code,department,graduation_year,gpa,skills,resume_link FROM students WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){r.next();return row("id",r.getLong(1),"name",r.getString(2),"email",r.getString(3),"studentCode",r.getString(4),"branch",r.getString(5),"year",r.getInt(6),"cgpa",r.getBigDecimal(7),"skills",r.getString(8),"resume",r.getString(9));}}}
 private static Map<String,Object> saveProfile(long id,Map<String,Object>b)throws SQLException{String name=req(b,"name",120),branch=req(b,"branch",100),skills=opt(b,"skills",500),resume=opt(b,"resume",500);double gpa=decimal(b,"cgpa",0,10);int year=integer(b,"year",2020,2100);try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("UPDATE students SET full_name=?,department=?,gpa=?,skills=?,resume_link=?,graduation_year=? WHERE id=?")){p.setString(1,name);p.setString(2,branch);p.setDouble(3,gpa);p.setString(4,skills);p.setString(5,resume);p.setInt(6,year);p.setLong(7,id);p.executeUpdate();}return profile(id);}
 private static void updateStudentCode(long id,Map<String,Object>b)throws SQLException{String code=req(b,"studentCode",40);try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("UPDATE students SET student_code=? WHERE id=?")){p.setString(1,code);p.setLong(2,id);if(p.executeUpdate()==0)throw new IllegalArgumentException("Student account not found.");}}private static List<Map<String,Object>> applications(User u)throws SQLException{List<Map<String,Object>>o=new ArrayList<>();String q="SELECT a.id,a.status,a.stage,a.applied_on,d.id drive_id,d.title,d.location,d.package_lpa,c.name company FROM applications a JOIN drives d ON d.id=a.drive_id JOIN companies c ON c.id=d.company_id WHERE a.student_id=? ORDER BY a.applied_on DESC";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,u.id);try(ResultSet r=p.executeQuery()){while(r.next()){long id=r.getLong(1);o.add(row("id",id,"status",r.getString(2),"stage",r.getString(3),"appliedOn",r.getDate(4).toString(),"driveId",r.getLong(5),"drive",r.getString(6),"location",r.getString(7),"package",r.getBigDecimal(8),"company",r.getString(9),"history",historyRows(c,id)));}}}return o;}
private static List<Map<String,Object>> applicationHistory(long app,long student)throws SQLException{try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT id FROM applications WHERE id=? AND student_id=?")){p.setLong(1,app);p.setLong(2,student);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Application not found.");return historyRows(c,app);}}}
private static List<Map<String,Object>> historyRows(Connection c,long id)throws SQLException{List<Map<String,Object>>h=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT status,stage,changed_at FROM application_history WHERE application_id=? ORDER BY changed_at,id")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){while(r.next())h.add(row("status",r.getString(1),"stage",r.getString(2),"at",r.getTimestamp(3).toString()));}}return h;}
private static void recordHistory(Connection c,long app,String status,String stage,long actor)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO application_history(application_id,status,stage,changed_by) VALUES(?,?,?,?)")){p.setLong(1,app);p.setString(2,status);p.setString(3,stage);p.setLong(4,actor);p.executeUpdate();}}
private static void apply(long student,long drive)throws SQLException{try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("INSERT INTO applications(student_id,drive_id,company_id,role,package_lpa) SELECT ?,d.id,d.company_id,d.title,d.package_lpa FROM drives d JOIN students s ON s.id=? WHERE d.id=? AND d.status='Open' AND d.apply_by>=CURRENT_DATE AND s.gpa>=d.eligibility_gpa AND (d.eligibility_branch='All branches' OR FIND_IN_SET(s.department,d.eligibility_branch)>0)")){p.setLong(1,student);p.setLong(2,student);p.setLong(3,drive);if(p.executeUpdate()==0)throw new IllegalArgumentException("Drive closed, already applied, or eligibility requirements not met.");}try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT id FROM applications WHERE student_id=? AND drive_id=?")){p.setLong(1,student);p.setLong(2,drive);try(ResultSet r=p.executeQuery()){if(r.next())recordHistory(c,r.getLong(1),"Applied","Applied",student);}}}private static Map<String,Object> saveDrive(Map<String,Object>b,long id)throws SQLException{int company=integer(b,"companyId",1,1000000);String title=req(b,"title",140),loc=req(b,"location",140),branches=req(b,"branches",300),description=opt(b,"description",800),date=req(b,"applyBy",10);double pack=decimal(b,"package",0,99999),gpa=decimal(b,"minGpa",0,10);String status=opt(b,"status",20);if(!Set.of("Open","Closed").contains(status))status="Open";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(id==0?"INSERT INTO drives(company_id,title,location,package_lpa,eligibility_gpa,eligibility_branch,description,apply_by,status) VALUES(?,?,?,?,?,?,?,?,?)":"UPDATE drives SET company_id=?,title=?,location=?,package_lpa=?,eligibility_gpa=?,eligibility_branch=?,description=?,apply_by=?,status=? WHERE id=?",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,company);p.setString(2,title);p.setString(3,loc);p.setDouble(4,pack);p.setDouble(5,gpa);p.setString(6,branches);p.setString(7,description);p.setDate(8,java.sql.Date.valueOf(date));p.setString(9,status);if(id!=0)p.setLong(10,id);p.executeUpdate();if(id==0)try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getLong(1);}}return row("id",id);}
 private static Map<String,Object> saveCompany(Map<String,Object>b,long id)throws SQLException{String name=req(b,"name",140),industry=req(b,"industry",100),location=req(b,"location",140);String q=id==0?"INSERT INTO companies(name,industry,location) VALUES(?,?,?)":"UPDATE companies SET name=?,industry=?,location=? WHERE id=?";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,industry);p.setString(3,location);if(id!=0)p.setLong(4,id);p.executeUpdate();if(id==0)try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getLong(1);}}return row("id",id);}
 private static void deleteCompany(long id)throws SQLException{try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("DELETE FROM companies WHERE id=?")){p.setLong(1,id);p.executeUpdate();}} private static void deleteDrive(long id)throws SQLException{try(Connection c=Database.connect()){c.setAutoCommit(false);try(PreparedStatement a=c.prepareStatement("DELETE FROM applications WHERE drive_id=?")){a.setLong(1,id);a.executeUpdate();}try(PreparedStatement d=c.prepareStatement("DELETE FROM drives WHERE id=?")){d.setLong(1,id);d.executeUpdate();}c.commit();}catch(SQLException e){throw e;}}private static List<Map<String,Object>> driveApplicants(long id)throws SQLException{List<Map<String,Object>>o=new ArrayList<>();String q="SELECT a.id,a.status,a.stage,a.applied_on,s.id studentId,s.full_name,s.email,s.department,s.gpa,s.skills,s.resume_link FROM applications a JOIN students s ON s.id=a.student_id WHERE a.drive_id=? ORDER BY a.applied_on DESC";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,id);try(ResultSet r=p.executeQuery()){while(r.next())o.add(row("id",r.getLong(1),"status",r.getString(2),"stage",r.getString(3),"appliedOn",r.getDate(4).toString(),"studentId",r.getLong(5),"name",r.getString(6),"email",r.getString(7),"branch",r.getString(8),"cgpa",r.getBigDecimal(9),"skills",r.getString(10),"resume",r.getString(11)));}}return o;}
 private static void updateApplication(long id,Map<String,Object>b,long actor)throws SQLException{String status=req(b,"status",30),stage=req(b,"stage",40);if(!Set.of("Applied","Under Review","Shortlisted","Rejected","Selected").contains(status)||!Set.of("Applied","Resume Screening","Assessment","Interview","Offer").contains(stage))throw new IllegalArgumentException("Select a valid status and stage.");try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("UPDATE applications SET status=?,stage=? WHERE id=?")){p.setString(1,status);p.setString(2,stage);p.setLong(3,id);if(p.executeUpdate()==0)throw new IllegalArgumentException("Application not found.");recordHistory(c,id,status,stage,actor);}}private static Map<String,Object> stats()throws SQLException{try(Connection c=Database.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT (SELECT COUNT(*) FROM students),(SELECT COUNT(*) FROM drives WHERE status='Open'),(SELECT COUNT(*) FROM applications),(SELECT COUNT(*) FROM applications WHERE status='Selected')")){r.next();return row("students",r.getInt(1),"drives",r.getInt(2),"applications",r.getInt(3),"selected",r.getInt(4));}}
 private static String req(Map<String,Object>b,String k,int max){String v=String.valueOf(b.getOrDefault(k,"")).trim();if(v.isBlank()||v.length()>max)throw new IllegalArgumentException("Check the "+k+" field.");return v;}private static String opt(Map<String,Object>b,String k,int max){String v=String.valueOf(b.getOrDefault(k,"")).trim();if(v.length()>max)throw new IllegalArgumentException(k+" is too long.");return v;}private static int integer(Map<String,Object>b,String k,int min,int max){try{int n=Integer.parseInt(String.valueOf(b.get(k)));if(n<min||n>max)throw new Exception();return n;}catch(Exception e){throw new IllegalArgumentException("Check "+k+".");}}private static double decimal(Map<String,Object>b,String k,double min,double max){try{double n=Double.parseDouble(String.valueOf(b.get(k)));if(!Double.isFinite(n)||n<min||n>max)throw new Exception();return n;}catch(Exception e){throw new IllegalArgumentException("Check "+k+".");}}
 @SuppressWarnings("unchecked")private static Map<String,Object> body(HttpExchange x)throws IOException{Object o=Json.parse(new String(x.getRequestBody().readNBytes(32769),StandardCharsets.UTF_8));if(!(o instanceof Map<?,?>))throw new IllegalArgumentException("Expected JSON object.");return(Map<String,Object>)o;}private static Map<String,Object> row(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<v.length;i+=2)m.put((String)v[i],v[i+1]);return m;}
 private static void json(HttpExchange x,int code,Object value)throws IOException{byte[]b=Json.stringify(value).getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.getResponseHeaders().set("Cache-Control","no-store");x.sendResponseHeaders(code,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}
 private static void staticFile(HttpExchange x)throws IOException{String p=x.getRequestURI().getPath();if(p.equals("/"))p="/index.html";Path f=STATIC.resolve(p.substring(1)).normalize();if(!f.startsWith(STATIC)||!Files.isRegularFile(f)){x.sendResponseHeaders(404,-1);x.close();return;}String type=Files.probeContentType(f);if(f.toString().endsWith(".js"))type="text/javascript; charset=utf-8";if(f.toString().endsWith(".css"))type="text/css; charset=utf-8";if(f.toString().endsWith(".html"))type="text/html; charset=utf-8";byte[]b=Files.readAllBytes(f);x.getResponseHeaders().set("Content-Type",type);x.sendResponseHeaders(200,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}
}
